import React, { useState, useEffect, useRef } from 'react';
import { useTheme } from '../contexts/ThemeContext';
import { useAuth } from '../contexts/AuthContext';
import { motion } from 'framer-motion';
import { useNotification } from '../components/NotificationContext';

// Import profile components
import ProfileInfo from '../components/profile/ProfileInfo';
import ProfileForm from '../components/profile/ProfileForm';
import StatsCard from '../components/profile/StatsCard';
import ThemeSettings from '../components/profile/ThemeSettings';
import NotificationSettings from '../components/profile/NotificationSettings';
import AchievementSection from '../components/profile/AchievementSection';

// Existing imports
import NeuralPageWrapper from '../components/NeuralPageWrapper';

// Neural network background components
const NeuralNode = ({ x, y, size, delay, color = 'rgba(100, 200, 255, 0.6)' }) => (
  <div 
    className="absolute rounded-full"
    style={{
      width: size,
      height: size,
      top: `${y}%`,
      left: `${x}%`,
      backgroundColor: color,
      filter: 'blur(1px)',
      opacity: 0.3
    }}
  />
);

const NeuralConnection = ({ startX, startY, endX, endY, active }) => {
  const pathData = `M ${startX} ${startY} L ${endX} ${endY}`;
  
  return (
    <svg className="absolute inset-0 w-full h-full pointer-events-none overflow-visible">
      <path 
        d={pathData}
        stroke="rgba(100, 200, 255, 0.4)"
        strokeOpacity={active ? 0.3 : 0.1}
        strokeWidth={active ? 1 : 0.5}
        fill="none"
        strokeDasharray={active ? "none" : "3,3"}
      />
    </svg>
  );
};

// SVG Avatar Component
const AvatarSVG = ({ seed, size = 100, gender = 'neutral', onClick, customImage }) => {
  // State for animations when clicked
  const [isAnimating, setIsAnimating] = useState(false);

  // Handle click animations
  const handleClick = () => {
    if (onClick) onClick();
    setIsAnimating(true);
    setTimeout(() => setIsAnimating(false), 1000);
  };

  // Memoize avatar generation to prevent unnecessary re-renders
  const avatarData = React.useMemo(() => {
    // Generate colors deterministically based on seed
    const getColor = (str, index) => {
      // Colors based on gender
      const colorSchemes = {
        male: ['#4F46E5', '#06B6D4', '#3B82F6', '#1D4ED8', '#2563EB'],
        female: ['#EC4899', '#F472B6', '#DB2777', '#BE185D', '#9D174D'],
        neutral: ['#10B981', '#059669', '#047857', '#065F46', '#064E3B']
      };

      const scheme = colorSchemes[gender] || colorSchemes.neutral;
      const charCode = str.charCodeAt(index % str.length);
      return scheme[charCode % scheme.length];
    };
    
    // Generate face colors based on gender
    const getFaceColor = (gender) => {
      switch(gender) {
        case 'male': return '#E5E7EB';
        case 'female': return '#FCE7F3';
        default: return '#D1FAE5';
      }
    };
    
    // Generate unique parts based on seed
    const seedStr = seed?.toString() || 'default';
    return {
      bgColor: getColor(seedStr, 0),
      faceColor: getFaceColor(gender),
      eyeColor: getColor(seedStr, 2),
      mouthColor: getColor(seedStr, 3),
      eyeType: seedStr.charCodeAt(0) % 3,
      mouthType: seedStr.charCodeAt(1) % 3,
      accessoryType: seedStr.charCodeAt(2) % 5, // More accessory options for fun
      expressionType: isAnimating ? Math.floor(Math.random() * 3) : -1, // Random expression when animating
    };
  }, [seed, gender, isAnimating]);

  // If there's a custom uploaded image, use that instead of SVG
  if (customImage) {
    return (
      <div className={`relative rounded-full overflow-hidden border-2 ${isAnimating ? 'animate-bounce' : ''}`} style={{ width: size, height: size }} onClick={handleClick}>
        <img 
          src={customImage} 
          alt="User avatar" 
          className="w-full h-full object-cover"
        />
      </div>
    );
  }
  
  // Simplified eyes with gender-specific variations
  const eyesElement = (() => {
    // If animating, show a surprised expression
    if (isAnimating) {
      return (
        <>
          <circle cx="35" cy="45" r="6" fill={avatarData.eyeColor} />
          <circle cx="65" cy="45" r="6" fill={avatarData.eyeColor} />
          <circle cx="35" cy="45" r="2" fill="white" />
          <circle cx="65" cy="45" r="2" fill="white" />
        </>
      );
    }

    // Normal eyes based on gender and type
    switch(avatarData.eyeType) {
      case 0:
        return (
          <>
            <circle cx="35" cy="45" r="5" fill={avatarData.eyeColor} />
            <circle cx="65" cy="45" r="5" fill={avatarData.eyeColor} />
            {gender === 'female' && (
              <>
                <path d="M25,40 Q35,35 45,40" stroke={avatarData.eyeColor} strokeWidth="1.5" fill="none" />
                <path d="M55,40 Q65,35 75,40" stroke={avatarData.eyeColor} strokeWidth="1.5" fill="none" />
              </>
            )}
          </>
        );
      case 1:
        return gender === 'male' ? (
          <>
            <rect x="30" y="40" width="10" height="8" rx="2" fill={avatarData.eyeColor} />
            <rect x="60" y="40" width="10" height="8" rx="2" fill={avatarData.eyeColor} />
          </>
        ) : (
          <>
            <path d="M30,45 Q35,40 40,45" stroke={avatarData.eyeColor} strokeWidth="2" fill="none" />
            <path d="M60,45 Q65,40 70,45" stroke={avatarData.eyeColor} strokeWidth="2" fill="none" />
            <circle cx="35" cy="45" r="2" fill={avatarData.eyeColor} />
            <circle cx="65" cy="45" r="2" fill={avatarData.eyeColor} />
          </>
        );
      default:
        return (
          <>
            <circle cx="35" cy="45" r="4" fill={avatarData.eyeColor} />
            <circle cx="65" cy="45" r="4" fill={avatarData.eyeColor} />
            <circle cx="35" cy="45" r="1" fill="white" />
            <circle cx="65" cy="45" r="1" fill="white" />
          </>
        );
    }
  })();
  
  // Mouth variations with expressions
  const mouthElement = (() => {
    // If animating, show a surprised mouth
    if (avatarData.expressionType === 0) {
      return <circle cx="50" cy="65" r="8" fill={avatarData.mouthColor} />;
    }
    
    if (avatarData.expressionType === 1) {
      return <path d="M30,65 Q50,85 70,65" stroke={avatarData.mouthColor} strokeWidth="3" fill="none" />;
    }
    
    if (avatarData.expressionType === 2) {
      return (
        <>
          <path d="M35,65 Q50,55 65,65" stroke={avatarData.mouthColor} strokeWidth="3" fill="none" />
          <path d="M42,74 L58,74" stroke={avatarData.mouthColor} strokeWidth="2" />
        </>
      );
    }

    // Normal mouth based on type
    switch(avatarData.mouthType) {
      case 0:
        return <path d="M40,65 Q50,75 60,65" stroke={avatarData.mouthColor} strokeWidth="2" fill="none" />;
      case 1:
        return <rect x="40" y="65" width="20" height="6" rx="3" fill={avatarData.mouthColor} />;
      default:
        return gender === 'female' ? (
          <path d="M35,65 Q50,72 65,65" stroke={avatarData.mouthColor} strokeWidth="3" fill="none" />
        ) : (
          <path d="M35,65 Q50,60 65,65" stroke={avatarData.mouthColor} strokeWidth="3" fill="none" />
        );
    }
  })();
  
  // Gender-specific accessories
  const accessoryElement = (() => {
    // Male-specific accessories
    if (gender === 'male') {
      switch(avatarData.accessoryType) {
        case 0:
          return <rect x="30" y="20" width="40" height="15" rx="5" fill="#4B5563" />; // Glasses
        case 1:
          return <path d="M25,25 L75,25 L75,30 L25,30 Z" fill="#1F2937" />; // Sunglasses
        case 2:
          return <path d="M30,15 Q50,5 70,15 L70,25 L30,25 Z" fill="#1F2937" />; // Hat
        default:
          return <path d="M25,30 L45,20 L55,20 L75,30" stroke="#1F2937" strokeWidth="2" fill="none" />; // Eyebrows
      }
    }
    
    // Female-specific accessories
    if (gender === 'female') {
      switch(avatarData.accessoryType) {
        case 0:
          return <path d="M20,30 Q50,10 80,30" stroke="#FFD700" strokeWidth="2" fill="none" />; // Crown
        case 1:
          return (
            <>
              <path d="M20,25 Q35,15 50,25 Q65,15 80,25" stroke="#FF69B4" strokeWidth="2" fill="none" />
              <circle cx="20" cy="25" r="3" fill="#FF69B4" />
              <circle cx="50" cy="25" r="3" fill="#FF69B4" />
              <circle cx="80" cy="25" r="3" fill="#FF69B4" />
            </>
          ); // Flower crown
        case 2:
          return <path d="M30,25 A20,10 0 0,1 70,25" stroke="#EC4899" strokeWidth="3" fill="none" />; // Hair band
        default:
          return (
            <>
              <circle cx="25" cy="30" r="5" fill="#9D174D" />
              <circle cx="75" cy="30" r="5" fill="#9D174D" />
            </>
          ); // Earrings
      }
    }
    
    // Neutral accessories
    switch(avatarData.accessoryType) {
      case 0:
        return <path d="M50,10 L60,25 L40,25 Z" fill="#047857" />; // Hat
      case 1:
        return <path d="M30,20 Q50,10 70,20" stroke="#047857" strokeWidth="2" fill="none" />; // Headband
      default:
        return null; // No accessory
    }
  })();
  
  return (
    <svg 
      width={size} 
      height={size} 
      viewBox="0 0 100 100" 
      xmlns="http://www.w3.org/2000/svg"
      onClick={handleClick}
      className={`cursor-pointer transition-all ${isAnimating ? 'scale-110' : ''}`}
    >
      {/* Background */}
      <circle cx="50" cy="50" r="50" fill={avatarData.bgColor} />
      
      {/* Face */}
      <circle cx="50" cy="50" r="35" fill={avatarData.faceColor} />
      
      {/* Eyes */}
      {eyesElement}
      
      {/* Mouth */}
      {mouthElement}
      
      {/* Accessory */}
      {accessoryElement}
      
      {/* Neural network overlay - animated when clicked */}
      <circle 
        cx="50" 
        cy="50" 
        r="48" 
        stroke="rgba(255,255,255,0.2)" 
        strokeWidth="0.5" 
        fill="none" 
        strokeDasharray="3,3"
        className={isAnimating ? 'animate-pulse' : ''}
      />
      
      {/* Subtle glow effect for fun */}
      {isAnimating && (
        <circle 
          cx="50" 
          cy="50" 
          r="52" 
          fill="none"
          stroke={avatarData.bgColor}
          strokeWidth="2"
          opacity="0.6"
        >
          <animate 
            attributeName="r" 
            from="52" 
            to="60" 
            dur="1s" 
            begin="0s" 
            fill="freeze" 
          />
          <animate 
            attributeName="opacity" 
            from="0.6" 
            to="0" 
            dur="1s" 
            begin="0s" 
            fill="freeze" 
          />
        </circle>
      )}
    </svg>
  );
};

const Profile = () => {
  const { theme } = useTheme();
  const { user, updateUserData, logout, isOfflineMode } = useAuth();
  const { addNotification } = useNotification();
  
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [profileData, setProfileData] = useState({
    name: '',
    gender: 'neutral',
    major: '',
    avatar_url: ''
  });
  
  // Load profile data when component mounts
  useEffect(() => {
    if (user && user.profile) {
      setProfileData({
        name: user.profile.name || '',
        gender: user.profile.gender || 'neutral',
        major: user.profile.major || '',
        avatar_url: user.profile.avatar_url || ''
      });
      setLoading(false);
    } else if (user) {
      // User logged in but no profile data
      setProfileData({
        name: user.email ? user.email.split('@')[0] : '',
        gender: 'neutral',
        major: '',
        avatar_url: ''
      });
      setLoading(false);
    }
  }, [user]);
  
  // Handle input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfileData(prev => ({
      ...prev,
      [name]: value
    }));
  };
  
  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    
    try {
      const result = await updateUserData(profileData);
      
      if (result.success) {
        addNotification('Profile updated successfully', 'success');
      } else {
        throw new Error(result.error || 'Failed to update profile');
      }
    } catch (error) {
      console.error('Error updating profile:', error);
      addNotification(`Failed to update profile: ${error.message}`, 'error');
    } finally {
      setSaving(false);
    }
  };
  
  // Handle logout
  const handleLogout = async () => {
    try {
      const result = await logout();
      
      if (result.success) {
        addNotification('Logged out successfully', 'success');
      } else {
        throw new Error(result.error || 'Failed to logout');
      }
    } catch (error) {
      console.error('Error logging out:', error);
      addNotification(`Failed to logout: ${error.message}`, 'error');
    }
  };
  
  if (loading) {
    return (
      <div className="flex justify-center items-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-neural-primary"></div>
      </div>
    );
  }
  
  return (
    <div className="w-full max-w-4xl mx-auto p-4">
      {isOfflineMode && (
        <div className="mb-4 p-3 bg-yellow-500/20 border border-yellow-500/30 rounded-lg">
          <p className="text-yellow-300 text-sm">
            You're currently in offline mode. Profile changes will be saved locally and synced when connection is restored.
          </p>
        </div>
      )}
      
      <motion.div 
        className="mb-6 p-6 bg-gray-800/80 backdrop-blur-sm rounded-xl shadow-lg border border-gray-700"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
      >
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-white">Your Profile</h2>
          
          <motion.button
            onClick={handleLogout}
            className="px-4 py-2 bg-red-500/20 text-red-300 rounded-lg hover:bg-red-500/30 transition-colors"
            whileHover={{ scale: 1.03 }}
            whileTap={{ scale: 0.97 }}
          >
            Logout
          </motion.button>
        </div>
        
        <div className="flex flex-col md:flex-row gap-8">
          <div className="w-full md:w-1/3 flex flex-col items-center">
            <div className="w-32 h-32 rounded-full overflow-hidden bg-gray-700 mb-4 flex items-center justify-center">
              {profileData.avatar_url ? (
                <img 
                  src={profileData.avatar_url} 
                  alt={profileData.name} 
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center bg-neural-primary text-4xl text-white font-bold">
                  {profileData.name ? profileData.name[0].toUpperCase() : '?'}
                </div>
              )}
            </div>
            
            <div className="text-center">
              <h3 className="text-xl font-bold text-white">{profileData.name || 'User'}</h3>
              <p className="text-gray-400">{user?.email}</p>
            </div>
            
            {user?.profile?.streak_days > 0 && (
              <div className="mt-4 bg-neural-primary/20 rounded-lg px-4 py-2 text-center">
                <span className="text-neural-primary text-sm">Current Streak</span>
                <p className="text-white text-xl font-bold">{user.profile.streak_days} days</p>
              </div>
            )}
          </div>
          
          <div className="w-full md:w-2/3">
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm text-gray-400 mb-1">Display Name</label>
                <input
                  type="text"
                  name="name"
                  className="w-full p-3 bg-gray-900/50 border border-gray-700 rounded-lg text-white placeholder-gray-400"
                  placeholder="Your name"
                  value={profileData.name}
                  onChange={handleChange}
                />
              </div>
              
              <div>
                <label className="block text-sm text-gray-400 mb-1">Major/Field of Study</label>
                <input
                  type="text"
                  name="major"
                  className="w-full p-3 bg-gray-900/50 border border-gray-700 rounded-lg text-white placeholder-gray-400"
                  placeholder="e.g. Computer Science"
                  value={profileData.major}
                  onChange={handleChange}
                />
              </div>
              
              <div>
                <label className="block text-sm text-gray-400 mb-1">Gender</label>
                <select
                  name="gender"
                  className="w-full p-3 bg-gray-900/50 border border-gray-700 rounded-lg text-white"
                  value={profileData.gender}
                  onChange={handleChange}
                >
                  <option value="male">Male</option>
                  <option value="female">Female</option>
                  <option value="neutral">Neutral</option>
                  <option value="other">Other</option>
                </select>
              </div>
              
              <div>
                <label className="block text-sm text-gray-400 mb-1">Avatar URL (optional)</label>
                <input
                  type="text"
                  name="avatar_url"
                  className="w-full p-3 bg-gray-900/50 border border-gray-700 rounded-lg text-white placeholder-gray-400"
                  placeholder="https://example.com/avatar.jpg"
                  value={profileData.avatar_url}
                  onChange={handleChange}
                />
              </div>
              
              <motion.button
                type="submit"
                className="w-full mt-6 p-3 bg-neural-primary hover:bg-neural-secondary transition-colors duration-200 rounded-lg text-white font-medium"
                whileHover={{ scale: 1.01 }}
                whileTap={{ scale: 0.99 }}
                disabled={saving}
              >
                {saving ? (
                  <span className="flex items-center justify-center">
                    <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Saving...
                  </span>
                ) : (
                  'Save Profile'
                )}
              </motion.button>
            </form>
          </div>
        </div>
      </motion.div>
      
      <motion.div
        className="p-6 bg-gray-800/80 backdrop-blur-sm rounded-xl shadow-lg border border-gray-700"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3, delay: 0.1 }}
      >
        <h2 className="text-xl font-bold mb-4 text-white">Study Stats</h2>
        
        {(!user?.studyData || user.studyData.length === 0) ? (
          <div className="p-6 text-center bg-gray-900/30 rounded-lg border border-gray-700">
            <p className="text-gray-400">You haven't tracked any study sessions yet. Start studying to see your stats!</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="p-4 bg-gray-900/30 rounded-lg border border-gray-700">
              <h3 className="text-gray-400 text-sm mb-1">Total Sessions</h3>
              <p className="text-2xl font-bold text-white">{user.studyData.length}</p>
            </div>
            
            <div className="p-4 bg-gray-900/30 rounded-lg border border-gray-700">
              <h3 className="text-gray-400 text-sm mb-1">Total Hours</h3>
              <p className="text-2xl font-bold text-white">
                {Math.round(user.studyData.reduce((total, session) => total + (session.duration || 0), 0) / 60)}
              </p>
            </div>
            
            <div className="p-4 bg-gray-900/30 rounded-lg border border-gray-700">
              <h3 className="text-gray-400 text-sm mb-1">Current Streak</h3>
              <p className="text-2xl font-bold text-white">{user.profile?.streak_days || 0} days</p>
            </div>
          </div>
        )}
      </motion.div>
    </div>
  );
};

export default Profile; 